import{_ as s,C as n,o as a,c as i,a3 as l,E as g,w as c,j as t,a as r}from"./chunks/framework.goqT_hzs.js";const d="/versions/cli/v1.3.43/screens/routing/virtual_a_out.png",h="/versions/cli/v1.3.43/screens/routing/virtual_a_in.png",p="/versions/cli/v1.3.43/screens/routing/usb_host_device_in.png",u="/versions/cli/v1.3.43/screens/routing/usb_host_device_missing.png",I="/versions/cli/v1.3.43/screens/routing/output_full.png",S=JSON.parse('{"title":"Routing","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/routing.md","filePath":"concepts/routing.md"}'),m={name:"concepts/routing.md"};function v(T,e,D,k,y,_){const o=n("ManualRelated");return a(),i("div",null,[e[1]||(e[1]=l('<h1 id="routing" tabindex="-1">Routing <a class="header-anchor" href="#routing" aria-label="Permalink to &quot;Routing&quot;">​</a></h1><p>The S32 sends and receives MIDI on its ports, and on four virtual ports that connect racks inside a project.</p><h2 id="physical-ports" tabindex="-1">Physical ports <a class="header-anchor" href="#physical-ports" aria-label="Permalink to &quot;Physical ports&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Port</th><th>Typical use</th></tr></thead><tbody><tr><td><strong>USB</strong></td><td>A computer or tablet (MIDI in and out)</td></tr><tr><td><strong>MIDI IN</strong>, <strong>MIDI OUT 1</strong>, <strong>MIDI OUT 2</strong></td><td>Hardware synths and drum machines (TRS + included DIN adapters)</td></tr><tr><td><strong>MIDI THRU</strong></td><td>A copy of whatever arrives at <strong>MIDI IN</strong></td></tr><tr><td><strong>USB HOST</strong></td><td>USB MIDI keyboard or controller plugged into the S32, or several through a powered hub</td></tr></tbody></table><h2 id="virtual-midi-a–d" tabindex="-1">Virtual MIDI A–D <a class="header-anchor" href="#virtual-midi-a–d" aria-label="Permalink to &quot;Virtual MIDI A–D&quot;">​</a></h2><p><strong>Virtual ports</strong> are internal cables between racks in the same project.</p><ol><li>Add <strong>MIDI OUT</strong> at the end of rack 1.</li><li>Set <strong>PORT</strong> to <strong>VIRTUAL A</strong> (or B, C, D).</li><li>In rack 2, add <strong>MIDI IN</strong>.</li><li>Set its <strong>PORT</strong> to <strong>VIRTUAL A</strong>.</li></ol><p>Use it to feed one rack&#39;s output into another, for example an arpeggiator in rack 1 driving a scaler in rack 2. Nothing reaches a real port unless a <strong>MIDI OUT</strong> sends it there.</p><p><img src="'+d+'" alt="Rack 01 MIDI OUT: PORT set to VIRTUAL A" class="screen"></p><p><img src="'+h+'" alt="Rack 02 MIDI IN: PORT set to VIRTUAL A" class="screen"></p><h2 id="usb-host" tabindex="-1">USB Host <a class="header-anchor" href="#usb-host" aria-label="Permalink to &quot;USB Host&quot;">​</a></h2><p>Choose <strong>USB HOST</strong> as the <strong>PORT</strong> to play a USB-only synth plugged into the rear <strong>HOST</strong> port. With a powered hub, several devices share the port.</p><p><strong>HOST DEVICE</strong>, right under <strong>PORT</strong>, picks which of them a rack uses. <strong>ALL</strong> hears every device and plays them all. Pick a device and the rack hears only that one, or plays only that one. Give each rack its own device: a keyboard drives one synth in rack 1 while a controller drives another in rack 2.</p><p><img src="'+p+'" alt="MIDI IN: PORT USB HOST, HOST DEVICE KEYBOARD" class="screen"></p><p>Every device you plug in shows up in the list. Unplug one and it stays there, dimmed: its rack goes quiet instead of switching to another device, and picks up again as soon as you plug it back in. A device that&#39;s the only one of its kind can go back in any hub port.</p><p><img src="'+u+'" alt="MIDI OUT: HOST DEVICE SYNTH, unplugged" class="screen"></p><p>Two identical devices are told apart by the hub port they&#39;re in: the lower port is <strong>(1)</strong>, the other <strong>(2)</strong>. Keep each in its port.</p><p>Changing <strong>HOST DEVICE</strong> stops the notes still playing, like changing <strong>PORT</strong>.</p><h2 id="midi-out" tabindex="-1">MIDI Out <a class="header-anchor" href="#midi-out" aria-label="Permalink to &quot;MIDI Out&quot;">​</a></h2><p>Every chain that should produce MIDI ends with a <strong>MIDI OUT</strong> device. Its <strong>PORT</strong> parameter picks:</p><ul><li><strong>USB</strong></li><li><strong>MIDI1</strong></li><li><strong>MIDI2</strong></li><li><strong>USB HOST</strong></li><li><strong>VIRTUAL A</strong>, <strong>B</strong>, <strong>C</strong>, <strong>D</strong></li></ul><h2 id="output-full" tabindex="-1">When an output is full <a class="header-anchor" href="#output-full" aria-label="Permalink to &quot;When an output is full {#output-full}&quot;">​</a></h2><p><strong>USB</strong>, <strong>MIDI1</strong>, <strong>MIDI2</strong> and <strong>USB HOST</strong> each send only so many notes at a time. When a project asks for more, the S32 skips some new notes and shows a warning triangle next to the BPM until two seconds after the last one. On <strong>USB</strong>, <strong>MIDI1</strong> and <strong>MIDI2</strong>, notes that already started still stop. A <strong>USB HOST</strong> device that can&#39;t keep up may miss other messages too.</p><p><img src="'+I+'" alt="Perform with the warning triangle next to the BPM" class="screen"></p><p>To hear every note, play fewer at once: lower <a href="./../devices/delay">Delay</a> <strong>REPETITIONS</strong> or <strong>FEEDBACK</strong>, use fewer <a href="./../devices/harmony">Harmony</a> intervals, cable fewer racks back into each other, or slow the tempo. <strong>USB</strong> carries more notes than <strong>MIDI1</strong> and <strong>MIDI2</strong>.</p>',25)),g(o,null,{default:c(()=>[...e[0]||(e[0]=[t("ul",null,[t("li",null,[t("a",{href:"./../racks/#rack-limits"},"Rack limits"),r(" — How many devices fit in a rack")]),t("li",null,[t("a",{href:"./../devices/midi-output"},"MIDI Out device"),r(" — Port selection per rack")]),t("li",null,[t("a",{href:"./../devices/"},"Device reference"),r(" — Every MIDI device type")])],-1)])]),_:1})])}const b=s(m,[["render",v]]);export{S as __pageData,b as default};
